validator:
function validate(input) {
  const [{ Customer = [] }] = input;
  const ids = new Set();
  for (const [id] of Customer) {
    if (id === null) return 'Every customer needs an id.';
    if (ids.has(id)) return `id ${id} appears twice in Customer.`;
    ids.add(id);
  }
  return null;
}

generator:
function generate(rand, size) {
  const names = ['Will', 'Jane', 'Alex', 'Bill', 'Zack', 'Mark', 'Ana', 'Lee'];
  const count = size === 'small' ? Math.floor(rand() * 9) : 2000;
  const Customer = [];
  for (let id = 1; id <= count; id++) {
    // Referees are often 2 or missing; other values may name anyone, even customers not in the table.
    const r = rand();
    const referee = r < 0.35 ? null : r < 0.65 ? 2 : 1 + Math.floor(rand() * (count + 3));
    Customer.push([id, names[Math.floor(rand() * names.length)], referee]);
  }
  return [{ Customer }];
}
